#include <Arduino.h>
#include <WiFi.h>
#include <WebServer.h>
#include <ESPmDNS.h>

#include "index_html.h"

// ============================================================
// PROJECT AETHER — DESIGN B
// Phone hotspot is the main network.
//
// Flow:
//   Aether-Setup AP
//        ↓
//   user enters phone hotspot SSID/password
//        ↓
//   ESP32 joins phone hotspot as STA
//        ↓
//   phone + ESP32 share the same network
//        ↓
//   browser accesses aether-node.local
//
// The ESP32 does NOT route Internet traffic.
// The PHONE HOTSPOT provides Internet access.
// ============================================================

// ---------- Provisioning AP ----------
static const char* SETUP_SSID = "Aether-Setup";
static const char* SETUP_PASSWORD = "aether1234";

// ---------- Final local hostname ----------
static const char* MDNS_HOSTNAME = "aether-node";

// ---------- Web server ----------
WebServer server(80);

// ---------- State ----------
bool staConnected = false;
bool provisioningComplete = false;

String targetSsid = "";
String targetPassword = "";

// ============================================================
// Helper: HTML escape
// ============================================================

String htmlEscape(const String& input) {
    String out;
    out.reserve(input.length() + 16);

    for (size_t i = 0; i < input.length(); ++i) {
        char c = input[i];

        switch (c) {
            case '&':
                out += "&amp;";
                break;
            case '<':
                out += "&lt;";
                break;
            case '>':
                out += "&gt;";
                break;
            case '"':
                out += "&quot;";
                break;
            case '\'':
                out += "&#39;";
                break;
            default:
                out += c;
                break;
        }
    }

    return out;
}

