// ============================================================
// Connect ESP32 to phone hotspot
// ============================================================

void handleConnect() {

    if (!server.hasArg("ssid") || !server.hasArg("password")) {
        server.send(
            400,
            "text/plain",
            "Missing SSID or password."
        );
        return;
    }

    targetSsid = server.arg("ssid");
    targetPassword = server.arg("password");

    targetSsid.trim();

    if (targetSsid.isEmpty()) {
        server.send(
            400,
            "text/plain",
            "SSID cannot be empty."
        );
        return;
    }

    Serial.println();
    Serial.println("=== HOTSPOT PROVISIONING ===");
    Serial.print("Target SSID: ");
    Serial.println(targetSsid);

    // Switch to AP+STA so we can still communicate with the phone
    // while the ESP32 attempts the connection.
    WiFi.mode(WIFI_AP_STA);

    Serial.println("Connecting ESP32 to phone hotspot...");

    WiFi.begin(
        targetSsid.c_str(),
        targetPassword.c_str()
    );

    const unsigned long timeoutMs = 20000;
    unsigned long start = millis();

    while (WiFi.status() != WL_CONNECTED &&
           millis() - start < timeoutMs) {

        delay(250);
        Serial.print(".");
    }

    Serial.println();

    if (WiFi.status() != WL_CONNECTED) {

        Serial.println("FAILED: Could not connect to hotspot.");

        WiFi.disconnect(false, false);

        String errorPage = R"rawliteral(
