// ============================================================
// Health endpoint
// ============================================================

void handleHealth() {

    String body = "{";

    body += "\"ok\":true";
    body += ",\"sta_connected\":";
    body += (WiFi.status() == WL_CONNECTED ? "true" : "false");

    if (WiFi.status() == WL_CONNECTED) {
        body += ",\"ip\":\"";
        body += WiFi.localIP().toString();
        body += "\"";

        body += ",\"hostname\":\"";
        body += MDNS_HOSTNAME;
        body += ".local\"";
    }

    body += "}";

    server.send(
        200,
        "application/json",
        body
    );
}

// ============================================================
// Main dashboard
// ============================================================

void handleDashboard() {

    // If connected as STA, serve actual Aether dashboard.
    if (WiFi.status() == WL_CONNECTED) {
        server.send_P(
            200,
            "text/html; charset=utf-8",
            INDEX_HTML
        );

        return;
    }

    // Otherwise show setup page.
    handleSetup();
}

// ============================================================
// Shutdown endpoint
// ============================================================

void handleDisconnect() {

    server.send(
        200,
        "text/plain",
        "AETHER_NODE_SHUTDOWN"
    );

    delay(200);

    Serial.println("Shutting down Wi-Fi...");

    MDNS.end();

    WiFi.softAPdisconnect(true);
    WiFi.disconnect(true, true);
    WiFi.mode(WIFI_OFF);

    delay(100);

    ESP.restart();
}

// ============================================================
// 404
// ============================================================

void handleNotFound() {

    if (WiFi.status() == WL_CONNECTED) {
        handleDashboard();
    } else {
        handleSetup();
    }
}

// ============================================================
// Setup
// ============================================================

void setup() {

    Serial.begin(115200);
    delay(500);

    Serial.println();
    Serial.println("=================================");
    Serial.println("      PROJECT AETHER");
    Serial.println("      DESIGN B / HOTSPOT");
    Serial.println("=================================");
    Serial.println();

    // Start provisioning AP.
    WiFi.mode(WIFI_AP);

    bool apStarted = WiFi.softAP(
        SETUP_SSID,
        SETUP_PASSWORD
    );

    if (!apStarted) {
        Serial.println("ERROR: Failed to start setup AP.");
    } else {
        Serial.println("Setup AP started.");
        Serial.print("SSID: ");
        Serial.println(SETUP_SSID);

        Serial.print("AP IP: ");
        Serial.println(WiFi.softAPIP());
    }

    // Routes.
    server.on(
        "/",
        HTTP_GET,
        handleDashboard
    );

    server.on(
        "/setup",
        HTTP_GET,
        handleSetup
    );

    server.on(
        "/connect",
        HTTP_POST,
        handleConnect
    );

    server.on(
        "/health",
        HTTP_GET,
        handleHealth
    );

    server.on(
        "/disconnect",
        HTTP_GET,
        handleDisconnect
    );

    server.onNotFound(
        handleNotFound
    );

    server.begin();

    Serial.println("HTTP server ready.");
    Serial.println();
    Serial.println("STEP 1:");
    Serial.println("Connect phone to Aether-Setup");
    Serial.println("Password: aether1234");
    Serial.println();
}

// ============================================================
// Loop
// ============================================================

void loop() {

    server.handleClient();

    // After successful provisioning, shut down the temporary
    // setup AP after a short period.
    //
    // We deliberately wait so the success page has time to reach
    // the phone before removing the setup network.
    static unsigned long provisioningStart = 0;

    if (provisioningComplete && provisioningStart == 0) {
        provisioningStart = millis();
    }

    if (provisioningComplete &&
        provisioningStart != 0 &&
        millis() - provisioningStart > 8000) {

        provisioningComplete = false;

        Serial.println();
        Serial.println("Disabling temporary Aether-Setup AP...");

        WiFi.softAPdisconnect(true);

        Serial.println("Temporary AP disabled.");
        Serial.println("STA network remains active.");
        Serial.print("STA IP: ");
        Serial.println(WiFi.localIP());

        if (MDNS.begin(MDNS_HOSTNAME)) {
            Serial.print("mDNS: http://");
            Serial.print(MDNS_HOSTNAME);
            Serial.println(".local/");
        }
    }

    delay(2);
}

