<body>

<div class="card">

<h1>
Project Aether — Secure Retrieval
</h1>

<p>
This dashboard is served directly by the ESP32.
The phone hotspot provides Internet access.
The blockchain stores verification metadata and IPFS stores the file.
</p>

<div class="row">

<label>
4-digit access PIN
</label>

<input
    id="pin"
    inputmode="numeric"
    maxlength="4"
    placeholder="4827"
>

</div>

<button id="go">
VERIFY & DOWNLOAD
</button>

<div
    id="status"
    class="status"
>
Waiting for PIN…
</div>

<div
    id="debug"
    class="debug"
>
System loading...
</div>

<p class="small">
Class-project MVP: the 4-digit PIN is a demo credential, not strong authentication.
</p>

</div>

<script>

// ============================================================
// PROJECT AETHER BLOCKCHAIN CONFIGURATION
// ============================================================

const RPC_URL =
    "https://base-mainnet.g.alchemy.com/v2/alch_wE4l5QcffNreB_ZahJm1m";

const CONTRACT_ADDRESS =
    "0xA3FFBC19730222a2C0a85e65791B890B4ecd6C26";

const ABI = [
    "function getFile(bytes32 pinHash) view returns (string cid, bytes32 sha256Digest, string fileName, uint256 fileSize, uint256 createdAt, bool exists)"
];

// ============================================================
// UI helpers
// ============================================================

const statusElement =
    document.getElementById("status");

const debugElement =
    document.getElementById("debug");

const log = (
    message,
    ok = false
) => {

    statusElement.textContent = message;

    statusElement.className =
        "status " + (ok ? "ok" : "");

};

const debug = (
    message
) => {

    debugElement.textContent =
        message;

};

// ============================================================
// SHA-256
// ============================================================

async function sha256OfBlob(blob) {

    const buffer =
        await blob.arrayBuffer();

    const hash =
        await crypto.subtle.digest(
            "SHA-256",
            buffer
        );

    return "0x" +
        Array
            .from(
                new Uint8Array(hash)
            )
            .map(
                b =>
                    b.toString(16)
                    .padStart(2, "0")
            )
            .join("");

}

// ============================================================
// Configuration validation
// ============================================================

function validConfig() {

    return (
        !RPC_URL.includes("YOUR_") &&
        !CONTRACT_ADDRESS.includes("YOUR_")
    );

}

// ============================================================
// Main verification function
// ============================================================

async function run() {

    const pin =
        document
            .getElementById("pin")
            .value
            .trim();

    // --------------------------------------------
    // Validate PIN
    // --------------------------------------------

    if (!/^\d{4}$/.test(pin)) {

        log(
            "Enter exactly 4 digits."
        );

        return;
    }

    // --------------------------------------------
    // Validate config
    // --------------------------------------------

    if (!validConfig()) {

        log(
            "Dashboard is not configured.\n" +
            "Add the Alchemy RPC URL and contract address in index_html.h."
        );

        return;
    }

    // --------------------------------------------
    // Check ethers.js
    // --------------------------------------------

    if (
        typeof ethers === "undefined"
    ) {

        log(
            "FAILED ❌\n" +
            "ethers.js did not load.\n" +
            "Check phone Internet access."
        );

        return;
    }

    try {

        // ----------------------------------------
        // Step 1
        // ----------------------------------------

        log(
            "1/4 Hashing the PIN…"
        );

        const pinHash =
            ethers.utils.keccak256(
                ethers.utils.toUtf8Bytes(pin)
            );

        debug(
            "PIN hash: " + pinHash
        );

        // ----------------------------------------
        // Step 2
        // ----------------------------------------

        log(
            "2/4 Asking Base Sepolia for the file record…"
        );

        const provider =
            new ethers.providers.JsonRpcProvider(
                RPC_URL
            );

        const contract =
            new ethers.Contract(
                CONTRACT_ADDRESS,
                ABI,
                provider
            );

        const result =
            await contract.getFile(
                pinHash
            );

        debug(
            "CID: " + result.cid
        );

        if (!result.exists) {

            throw new Error(
                "PIN not found"
            );

        }

        // ----------------------------------------
        // Step 3
        // ----------------------------------------

        log(
            "3/4 Downloading the file from IPFS…"
        );

        const url =
            "https://ipfs.io/ipfs/" +
            result.cid;

        const response =
            await fetch(url);

        if (!response.ok) {

            throw new Error(
                "IPFS download failed: HTTP " +
                response.status
            );

        }

        const blob =
            await response.blob();

        // ----------------------------------------
        // Step 4
        // ----------------------------------------

        log(
            "4/4 Verifying SHA-256 integrity…"
        );

        const actual =
            await sha256OfBlob(blob);

        debug(
            "Expected: " +
            result.sha256Digest +
            "\nActual: " +
            actual
        );

        if (
            actual.toLowerCase() !==
            result.sha256Digest.toLowerCase()
        ) {

            throw new Error(
                "INTEGRITY CHECK FAILED"
            );

        }

        // ----------------------------------------
        // Download
        // ----------------------------------------

        const objectUrl =
            URL.createObjectURL(blob);

        const anchor =
            document.createElement("a");

        anchor.href =
            objectUrl;

        anchor.download =
            result.fileName ||
            "aether_payload.zip";

        document.body.appendChild(anchor);

        anchor.click();

        anchor.remove();

        URL.revokeObjectURL(
            objectUrl
        );

        // ----------------------------------------
        // SUCCESS
        // ----------------------------------------

        log(
            "VERIFIED ✅\n" +
            "File: " +
            result.fileName +
            "\n" +
            "Size: " +
            result.fileSize +
            " bytes\n" +
            "SHA-256 matches blockchain record.",
            true
        );

    } catch (error) {

        console.error(error);

        log(
            "FAILED ❌\n" +
            (
                error?.reason ||
                error?.message ||
                String(error)
            )
        );

    }

}

