async function sha256OfBlob(blob) {

    const buffer =
        await blob.arrayBuffer();

    const hash =
        await crypto.subtle.digest(
            "SHA-256",
            buffer
        );

    return "0x" +
        Array
            .from(
                new Uint8Array(hash)
            )
            .map(
                b =>
                    b.toString(16)
                    .padStart(2, "0")
            )
            .join("");

}

// ============================================================
