        // ----------------------------------------
        // Step 1
        // ----------------------------------------

        log(
            "1/4 Hashing the PIN…"
        );

        const pinHash =
            ethers.utils.keccak256(
                ethers.utils.toUtf8Bytes(pin)
            );

        debug("PIN hash: " + pinHash);

        // ----------------------------------------
        // Step 2
        // ----------------------------------------

        log(
            "2/4 Asking Base Sepolia for the file record…"
        );

        const provider =
            new ethers.providers.JsonRpcProvider(
                RPC_URL
            );

        const contract =
            new ethers.Contract(
                CONTRACT_ADDRESS,
                ABI,
                provider
            );

        const result = await contract.getFile(pinHash);

        debug("CID: " + result.cid);

        if (!result.exists) {

            throw new Error(
                "PIN not found"
            );

        }

        // ----------------------------------------
        // Step 3
        // ----------------------------------------

        log(
            "3/4 Downloading the file from IPFS…"
        );

        const gateways = [
            "https://gateway.pinata.cloud/ipfs/",
            "https://dweb.link/ipfs/",
            "https://ipfs.io/ipfs/",
            "https://cloudflare-ipfs.com/ipfs/"
        ];

        let blob = null;
        let lastError = null;

        for (const base of gateways) {
            const url = base + result.cid;
            log("Trying gateway: " + base);
            try {
                const response = await fetch(url);
                if (response.ok) {
                    blob = await response.blob();
                    log("Downloaded via: " + base);
                    break;
                }
                lastError = "HTTP " + response.status;
            } catch (e) {
                lastError = e.message;
            }
        }

        if (!blob) {
            throw new Error("All IPFS gateways failed. Last error: " + lastError);
        }

        // ----------------------------------------
        // Step 4 - Verify SHA-256 integrity (only on secure context)
        // ----------------------------------------

        let integrityVerified = false;

        if (window.crypto && window.crypto.subtle) {
            log("4/4 Verifying SHA-256 integrity…");
            try {
                const actual = await sha256OfBlob(blob);
                debug("Expected: " + result.sha256Digest + "\nActual: " + actual);
                if (actual.toLowerCase() !== result.sha256Digest.toLowerCase()) {
                    throw new Error("INTEGRITY CHECK FAILED");
                }
                integrityVerified = true;
                log("SHA-256 verified ✅");
            } catch (e) {
                throw new Error("Integrity verification failed: " + e.message);
            }
        } else {
            log("4/4 Skipping SHA-256 (requires HTTPS). File downloaded.");
        }

        // ----------------------------------------
        // Download
        // ----------------------------------------

        const objectUrl = URL.createObjectURL(blob);
        const anchor = document.createElement("a");
        anchor.href = objectUrl;
        anchor.download = result.fileName || "aether_payload.zip";
        document.body.appendChild(anchor);
        anchor.click();
        anchor.remove();
        URL.revokeObjectURL(objectUrl);

        // ----------------------------------------
        // SUCCESS
        // ----------------------------------------

        const verifyMsg = integrityVerified ? "SHA-256 matches blockchain record." : "Integrity check skipped (HTTP).";
        log(
            "DOWNLOADED ✅\n" +
            "File: " + result.fileName + "\n" +
            "Size: " + result.fileSize + " bytes\n" +
            verifyMsg,
            true
        );

