#include <Arduino.h>
#include <WiFi.h>
#include <WebServer.h>
#include <ESPmDNS.h>
#include <WiFiServerSecure.h>
#include <mbedtls/x509_crt.h>
#include <mbedtls/pk.h>
#include <mbedtls/entropy.h>
#include <mbedtls/ctr_drbg.h>
#include <mbedtls/sha256.h>
#include <driver/rtc_io.h>

#include "index_html.h"

// ============================================================
// PROJECT AETHER — TACTICAL NODE (HTTPS + PHYSICAL APPROVAL)
// ============================================================
//
// Flow:
//   1. Aether-Setup AP boots
//   2. Phone connects, enters hotspot creds via captive portal
//   3. ESP32 joins phone hotspot as STA (phone provides Internet)
//   4. mDNS advertises aether-node.local
//   4. HTTPS server starts on port 443 with self-signed cert
//   5. Phone reconnects to hotspot, opens https://aether-node.local/
//   6. Dashboard loads, user enters PIN
//   7. ESP32 generates session nonce, stores PIN hash + nonce
//   8. Dashboard queries blockchain with PIN hash
//   9. Dashboard fetches file from IPFS, verifies SHA-256 (HTTPS required)
//  10. PHYSICAL BUTTON PRESS required to authorize session
//  11. File downloads, renders ephemerally
//  12. Session expires (60s TTL) or 3 failed attempts
//  13. Long button hold (3s) = immediate air-gap (WiFi OFF)
//
// The ESP32 does NOT route Internet traffic.
// The PHONE HOTSPOT provides Internet access.
// ============================================================

// ---------- Provisioning AP ----------
static const char* SETUP_SSID = "Aether-Setup";
static const char* SETUP_PASSWORD = "aether1234";

// ---------- Final local hostname ----------
static const char* MDNS_HOSTNAME = "aether-node";

// ---------- Hardware pins ----------
static const int BUTTON_PIN = 4;        // GPIO 4 - Tactile button (active LOW with pullup)
static const int LED_RED_PIN = 18;      // GPIO 18 - Red LED
static const int LED_GREEN_PIN = 5;     // GPIO 5 - Green LED
static const int LED_BLUE_PIN = 19;     // GPIO 19 - Blue LED

// ---------- Session constants ----------
static const unsigned long SESSION_TTL_MS = 60000;      // 60 seconds
static const uint8_t MAX_ATTEMPTS = 3;                  // Max PIN attempts per session
static const unsigned long AIRGAP_HOLD_MS = 3000;       // 3 second hold = air-gap

// ---------- Web servers ----------
WebServer httpServer(80);           // HTTP (provisioning + redirect)
WiFiServerSecure httpsServer(443);  // HTTPS (dashboard + API)

// ---------- Certificate/Key (generated at boot) ----------
static String certPEM;
static String keyPEM;
static String certSHA256;           // For frontend pinning

// ---------- State ----------
enum class DeviceState {
    BOOT,
    PROVISIONING_AP,
    PROVISIONING_STA,
    OPERATIONAL,
    SESSION_PENDING,
    SESSION_AUTHORIZED,
    SESSION_COMPLETE,
    AIR_GAPPED
};

DeviceState currentState = DeviceState::BOOT;

struct Session {
    uint8_t nonce[32];
    uint8_t pinHash[32];
    unsigned long createdAt = 0;
    uint8_t attempts = 0;
    bool authorized = false;
    bool active = false;
    char fileName[64] = {0};
};

Session currentSession;
bool staConnected = false;
bool provisioningComplete = false;
String targetSsid = "";
String targetPassword = "";

// Button debouncing
volatile bool buttonPressed = false;
volatile bool buttonLongPress = false;
unsigned long buttonPressStart = 0;
bool buttonLastState = HIGH;

// Log buffer (RAM only, lost on reboot)
struct LogEntry {
    char timestamp[20];
    char event[48];
};
LogEntry logs[16];
int logCount = 0;

// ============================================================
// Helpers
// ============================================================

void addLog(const char* event) {
    if (logCount >= 16) return;
    time_t now = time(nullptr);
    strftime(logs[logCount].timestamp, 20, "%Y-%m-%d %H:%M:%S", localtime(&now));
    strncpy(logs[logCount].event, event, 47);
    logCount++;
}

String htmlEscape(const String& input) {
    String out;
    out.reserve(input.length() + 16);
    for (size_t i = 0; i < input.length(); ++i) {
        char c = input[i];
        switch (c) {
            case '&': out += "&"; break;
            case '<': out += "<"; break;
            case '>': out += ">"; break;
            case '"': out += """; break;
            case '\'': out += "'"; break;
            default: out += c; break;
        }
    }
    return out;
}

void setLEDs(bool red, bool green, bool blue) {
    digitalWrite(LED_RED_PIN, red ? HIGH : LOW);
    digitalWrite(LED_GREEN_PIN, green ? HIGH : LOW);
    digitalWrite(LED_BLUE_PIN, blue ? HIGH : LOW);
}

void blinkLED(int pin, int times, int delayMs) {
    for (int i = 0; i < times; i++) {
        digitalWrite(pin, HIGH);
        delay(delayMs);
        digitalWrite(pin, LOW);
        delay(delayMs);
    }
}

// ============================================================
// Certificate Generation (Self-signed at boot)
// ============================================================

void generateSelfSignedCert() {
    mbedtls_entropy_context entropy;
    mbedtls_ctr_drbg_context ctr_drbg;
    mbedtls_x509_crt crt;
    mbedtls_pk_context key;

    mbedtls_entropy_init(&entropy);
    mbedtls_ctr_drbg_init(&ctr_drbg);
    mbedtls_x509_crt_init(&crt);
    mbedtls_pk_init(&key);

    const char* pers = "aether_tactical_node";
    mbedtls_ctr_drbg_seed(&ctr_drbg, mbedtls_entropy_func, &entropy, (const unsigned char*)pers, strlen(pers));

    // Generate EC key (secp256r1)
    mbedtls_pk_setup(&key, mbedtls_pk_info_from_type(MBEDTLS_PK_ECKEY));
    mbedtls_ecp_gen_key(MBEDTLS_ECP_DP_SECP256R1, mbedtls_pk_ec(key), mbedtls_ctr_drbg_random, &ctr_drbg);

    // Write key to PEM
    unsigned char keyBuf[2048];
    int keyLen = mbedtls_pk_write_key_pem(&key, keyBuf, sizeof(keyBuf));
    keyPEM = String((char*)keyBuf, keyLen);

    // Generate self-signed cert
    mbedtls_x509_crt_set_subject_name(&crt, "CN=aether-node.local");
    mbedtls_x509_crt_set_issuer_name(&crt, "CN=aether-node.local");
    mbedtls_x509_crt_set_version(&crt, MBEDTLS_X509_CRT_VERSION_3);
    mbedtls_x509_crt_set_serial_raw(&crt, (unsigned char*)"AETHER", 6);
    mbedtls_x509_crt_set_key_usage(&crt, MBEDTLS_X509_KU_DIGITAL_SIGNATURE | MBEDTLS_X509_KU_KEY_ENCIPHERMENT);

    // Validity: 10 years
    mbedtls_x509_time now, exp;
    time_t t = time(nullptr);
    struct tm* tm_now = gmtime(&t);
    now.year = tm_now->tm_year + 1900; now.mon = tm_now->tm_mon + 1; now.day = tm_now->tm_mday;
    now.hour = tm_now->tm_hour; now.min = tm_now->tm_min; now.sec = tm_now->tm_sec;
    struct tm tm_exp = *tm_now;
    tm_exp.tm_year += 10;
    exp.year = tm_exp.tm_year + 1900; exp.mon = tm_exp.tm_mon + 1; exp.day = tm_exp.tm_mday;
    exp.hour = tm_exp.tm_hour; exp.min = tm_exp.tm_min; exp.sec = tm_exp.tm_sec;
    mbedtls_x509_crt_set_validity(&crt, &now, &exp);

    mbedtls_x509_crt_sign(&crt, &crt, &key, MBEDTLS_MD_SHA256, mbedtls_ctr_drbg_random, &ctr_drbg);

    // Write cert to PEM
    unsigned char certBuf[4096];
    int certLen = mbedtls_x509_crt_write_pem(&crt, certBuf, sizeof(certBuf));
    certPEM = String((char*)certBuf, certLen);

    // Compute SHA-256 of cert for pinning
    unsigned char sha256[32];
    mbedtls_sha256((const unsigned char*)certPEM.c_str(), certPEM.length(), sha256, 0);
    char shaHex[65];
    for (int i = 0; i < 32; i++) sprintf(shaHex + i * 2, "%02x", sha256[i]);
    shaHex[64] = 0;
    certSHA256 = "sha256/" + String(shaHex);

    // Cleanup
    mbedtls_x509_crt_free(&crt);
    mbedtls_pk_free(&key);
    mbedtls_ctr_drbg_free(&ctr_drbg);
    mbedtls_entropy_free(&entropy);

    Serial.println("Certificate generated.");
    Serial.print("Cert SHA-256: ");
    Serial.println(certSHA256);
}

// ============================================================
// Session Management
// ============================================================

void generateSessionNonce(uint8_t* nonce) {
    // Use ESP32 hardware RNG
    esp_fill_random(nonce, 32);
}

void createSession(const uint8_t* pinHash) {
    generateSessionNonce(currentSession.nonce);
    memcpy(currentSession.pinHash, pinHash, 32);
    currentSession.createdAt = millis();
    currentSession.attempts = 0;
    currentSession.authorized = false;
    currentSession.active = true;
    currentSession.fileName[0] = 0;

    currentState = DeviceState::SESSION_PENDING;
    addLog("session_created");
    setLEDs(false, false, true); // Blue = session pending
    Serial.println("Session created. Waiting for physical approval.");
}

bool isSessionValid() {
    if (!currentSession.active) return false;
    if (millis() - currentSession.createdAt > SESSION_TTL_MS) {
        currentSession.active = false;
        addLog("session_expired");
        return false;
    }
    if (currentSession.attempts >= MAX_ATTEMPTS) {
        currentSession.active = false;
        addLog("session_locked");
        return false;
    }
    return true;
}

void expireSession() {
    currentSession.active = false;
    currentSession.authorized = false;
    currentState = DeviceState::OPERATIONAL;
    setLEDs(false, true, false); // Green = operational
    addLog("session_ended");
}

bool verifyPin(const uint8_t* pinHash) {
    return memcmp(pinHash, currentSession.pinHash, 32) == 0;
}

// ============================================================
// Button Handling (Interrupt + Debounce)
// ============================================================

void IRAM_ATTR buttonISR() {
    bool currentState = digitalRead(BUTTON_PIN);
    if (currentState == LOW && buttonLastState == HIGH) {
        // Falling edge - button pressed
        buttonPressStart = millis();
        buttonPressed = true;
    } else if (currentState == HIGH && buttonLastState == LOW) {
        // Rising edge - button released
        buttonPressed = false;
        unsigned long pressDuration = millis() - buttonPressStart;
        if (pressDuration >= AIRGAP_HOLD_MS) {
            buttonLongPress = true;
        }
    }
    buttonLastState = currentState;
}

void checkButton() {
    if (buttonLongPress) {
        buttonLongPress = false;
        Serial.println("LONG PRESS DETECTED - AIR GAP");
        triggerAirGap();
    }
    if (buttonPressed && (millis() - buttonPressStart > 50)) {
        // Debounced press detected
        buttonPressed = false;
        if (currentState == DeviceState::SESSION_PENDING) {
            currentSession.authorized = true;
            currentState = DeviceState::SESSION_AUTHORIZED;
            setLEDs(false, true, false); // Green = authorized
            addLog("session_authorized");
            Serial.println("PHYSICAL APPROVAL GRANTED");
        }
    }
}

void triggerAirGap() {
    Serial.println("=== AIR GAP TRIGGERED ===");
    addLog("air_gap_triggered");

    // Immediate WiFi shutdown
    httpsServer.stop();
    httpServer.stop();
    MDNS.end();
    WiFi.softAPdisconnect(true);
    WiFi.disconnect(true, true);
    WiFi.mode(WIFI_OFF);

    currentState = DeviceState::AIR_GAPPED;
    expireSession();

    // LEDs off
    setLEDs(false, false, false);

    // Restart after 2 seconds to allow logs to be read via serial
    delay(2000);
    ESP.restart();
}

