void handleSessionCreate() {
    if (!httpsServer.hasArg("pin")) {
        httpsServer.send(400, "application/json", "{\"error\":\"PIN required\"}");
        return;
    }

    String pin = httpsServer.arg("pin");
    pin.trim();

    if (!isValidPin(pin)) {
        httpsServer.send(400, "application/json", "{\"error\":\"Enter exactly 4 digits\"}");
        return;
    }
        // Manual 4-digit check
        if (pin.length() != 4) {
            httpsServer.send(400, "application/json", "{\"error\":\"Enter exactly 4 digits\"}");
            return;
        }
        for (int i = 0; i < 4; i++) {
            if (pin[i] < '0' || pin[i] > '9') {
                httpsServer.send(400, "application/json", "{\"error\":\"Enter exactly 4 digits\"}");
                return;
            }
        }
    }

    // Compute PIN hash: keccak256(PIN || session_nonce)
    // For now, we'll use a simple approach - the frontend will compute this
    // and send the hash directly. Here we just create a session.
    uint8_t pinHash[32];
    // In production, the frontend sends the pinHash, not the raw PIN
    // For now, hash the PIN directly
    mbedtls_sha256((const unsigned char*)pin.c_str(), pin.length(), currentSession.pinHash, 0);

    createSession(currentSession.pinHash);

    // Return session nonce for frontend to use
    String nonceHex;
    for (int i = 0; i < 32; i++) {
        char buf[3];
        sprintf(buf, "%02x", currentSession.nonce[i]);
        nonceHex += buf;
    }

    String resp = "{\"session_nonce\":\"" + nonceHex + "\"}";
    httpsServer.send(200, "application/json", resp);
}

void handleSessionStatus() {
    String resp = "{";
    resp += "\"active\":" + String(currentSession.active ? "true" : "false");
    resp += ",\"authorized\":" + String(currentSession.authorized ? "true" : "false");
    resp += ",\"attempts\":" + String(currentSession.attempts);
    resp += ",\"ttl_remaining\":" + String(currentSession.active ? max(0L, (long)(SESSION_TTL_MS - (millis() - currentSession.createdAt))) : 0);
    resp += "}";
    httpsServer.send(200, "application/json", resp);
}

void handleSessionAuthorize() {
    if (!currentSession.active) {
        httpsServer.send(400, "application/json", "{\"error\":\"No active session\"}");
        return;
    }
    if (currentSession.authorized) {
        httpsServer.send(400, "application/json", "{\"error\":\"Already authorized\"}");
        return;
    }
    currentSession.authorized = true;
    currentState = DeviceState::SESSION_AUTHORIZED;
    setLEDs(false, true, false);
    addLog("session_authorized_via_api");
    httpsServer.send(200, "application/json", "{\"authorized\":true}");
}

void handleCert() {
    httpsServer.send(200, "application/x-pem-file", certPEM);
}

void handleCertSHA256() {
    httpsServer.send(200, "text/plain", certSHA256);
}

void handleLogs() {
    String json = "{\"logs\":[";
    for (int i = 0; i < logCount; i++) {
        json += "{\"time\":\"" + String(logs[i].timestamp) + "\",\"event\":\"" + String(logs[i].event) + "\"}";
        if (i < logCount - 1) json += ",";
    }
    json += "]}";
    httpsServer.send(200, "application/json", json);
}

// ============================================================
// HTTPS Dashboard
// ============================================================

void handleHTTPSDashboard() {
    if (!currentSession.active) {
        httpsServer.sendHeader("Location", "/health");
        httpsServer.send(302, "text/plain", "");
        return;
    }
    if (!currentSession.authorized) {
        httpsServer.send(403, "application/json", "{\"error\":\"Session not authorized. Physical button press required.\"}");
        return;
    }
    httpsServer.send_P(200, "text/html; charset=utf-8", INDEX_HTML);
}

// ============================================================
// Setup
// ============================================================

void setup() {
    Serial.begin(115200);
    delay(500);

    Serial.println();
    Serial.println("=================================");
    Serial.println("      PROJECT AETHER");
    Serial.println("      TACTICAL NODE v1.0");
    Serial.println("=================================");
    Serial.println();

    // Hardware init
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    pinMode(LED_RED_PIN, OUTPUT);
    pinMode(LED_GREEN_PIN, OUTPUT);
    pinMode(LED_BLUE_PIN, OUTPUT);
    setLEDs(false, false, false);

    // Button interrupt
    buttonLastState = digitalRead(BUTTON_PIN);
    attachInterrupt(digitalPinToInterrupt(BUTTON_PIN), buttonISR, CHANGE);

    // Generate self-signed certificate
    generateSelfSignedCert();

    // Start provisioning AP
    WiFi.mode(WIFI_AP);
    bool apStarted = WiFi.softAP(SETUP_SSID, SETUP_PASSWORD);
    if (!apStarted) {
        Serial.println("ERROR: Failed to start setup AP.");
        setLEDs(true, false, false);
    } else {
        Serial.println("Setup AP started.");
        Serial.print("SSID: "); Serial.println(SETUP_SSID);
        Serial.print("AP IP: "); Serial.println(WiFi.softAPIP());
        setLEDs(false, false, true); // Blue = provisioning
    }

    // HTTP routes (provisioning)
    httpServer.on("/", HTTP_GET, []( ) { handleSetup(); });
    httpServer.on("/setup", HTTP_GET, []( ) { handleSetup(); });
    httpServer.on("/connect", HTTP_POST, []( ) { handleConnect(); });
    httpServer.on("/health", HTTP_GET, []( ) { handleHealth(); });
    httpServer.on("/cert", HTTP_GET, []( ) { handleCert(); });
    httpServer.on("/cert/sha256", HTTP_GET, []( ) { handleCertSHA256(); });
    httpServer.on("/logs", HTTP_GET, []( ) { handleLogs(); });
    httpServer.onNotFound([]( ) {
        if (WiFi.status() == WL_CONNECTED) {
            httpsServer.sendHeader("Location", "/health");
            httpsServer.send(302, "text/plain", "");
        } else {
            handleSetup();
        }
    });
    httpServer.begin();

    Serial.println("HTTP server ready (port 80).");
    Serial.println();
    Serial.println("STEP 1:");
    Serial.println("Connect phone to Aether-Setup");
    Serial.println("Password: aether1234");
    Serial.println();
}

