void addLog(const char* event) {
    if (logCount >= 16) return;
    time_t now = time(nullptr);
    strftime(logs[logCount].timestamp, 20, "%Y-%m-%d %H:%M:%S", localtime(&now));
    strncpy(logs[logCount].event, event, 47);
    logCount++;
}

String htmlEscape(const String& input) {
    String out;
    out.reserve(input.length() + 16);
    for (size_t i = 0; i < input.length(); ++i) {
        char c = input[i];
        switch (c) {
            case '&': out += "&"; break;
            case '<': out += "<"; break;
            case '>': out += ">"; break;
            case '"': out += """; break;
            case '\'': out += "'"; break;
            default: out += c; break;
        }
    }
    return out;
}

void setLEDs(bool red, bool green, bool blue) {
    digitalWrite(LED_RED_PIN, red ? HIGH : LOW);
    digitalWrite(LED_GREEN_PIN, green ? HIGH : LOW);
    digitalWrite(LED_BLUE_PIN, blue ? HIGH : LOW);
}

void blinkLED(int pin, int times, int delayMs) {
    for (int i = 0; i < times; i++) {
        digitalWrite(pin, HIGH);
        delay(delayMs);
        digitalWrite(pin, LOW);
        delay(delayMs);
    }
}

bool isValidPin(const String& pin) {
    if (pin.length() != 4) return false;
    for (int i = 0; i < 4; i++) {
        if (pin[i] < '0' || pin[i] > '9') return false;
    }
    return true;
}

// ============================================================
// Certificate Generation (Self-signed at boot)
// ============================================================

void generateSelfSignedCert() {
    mbedtls_entropy_context entropy;
    mbedtls_ctr_drbg_context ctr_drbg;
    mbedtls_x509_crt crt;
    mbedtls_pk_context key;

    mbedtls_entropy_init(&entropy);
    mbedtls_ctr_drbg_init(&ctr_drbg);
    mbedtls_x509_crt_init(&crt);
    mbedtls_pk_init(&key);

    const char* pers = "aether_tactical_node";
    mbedtls_ctr_drbg_seed(&ctr_drbg, mbedtls_entropy_func, &entropy, (const unsigned char*)pers, strlen(pers));

    // Generate EC key (secp256r1)
    mbedtls_pk_setup(&key, mbedtls_pk_info_from_type(MBEDTLS_PK_ECKEY));
    mbedtls_ecp_gen_key(MBEDTLS_ECP_DP_SECP256R1, mbedtls_pk_ec(key), mbedtls_ctr_drbg_random, &ctr_drbg);

    // Write key to PEM
    unsigned char keyBuf[2048];
    int keyLen = mbedtls_pk_write_key_pem(&key, keyBuf, sizeof(keyBuf));
    keyPEM = String((char*)keyBuf, keyLen);

    // Generate self-signed cert using mbedtls_x509write_crt
    mbedtls_x509write_cert crt_write;
    mbedtls_x509write_crt_init(&crt_write);
    mbedtls_x509write_crt_set_subject_key(&crt_write, &key);
    mbedtls_x509write_crt_set_issuer_key(&crt_write, &key);

    mbedtls_x509write_crt_set_subject_name(&crt_write, "CN=aether-node.local");
    mbedtls_x509write_crt_set_issuer_name(&crt_write, "CN=aether-node.local");
    mbedtls_x509write_crt_set_version(&crt_write, MBEDTLS_X509_CRT_VERSION_3);
    mbedtls_x509write_crt_set_serial_raw(&crt_write, (const unsigned char*)"AETHER", 6);
    mbedtls_x509write_crt_set_key_usage(&crt_write, MBEDTLS_X509_KU_DIGITAL_SIGNATURE | MBEDTLS_X509_KU_KEY_ENCIPHERMENT);

    // Validity: 10 years
    mbedtls_x509_time now, exp;
    time_t t = time(nullptr);
    struct tm* tm_now = gmtime(&t);
    now.year = tm_now->tm_year + 1900; now.mon = tm_now->tm_mon + 1; now.day = tm_now->tm_mday;
    now.hour = tm_now->tm_hour; now.min = tm_now->tm_min; now.sec = tm_now->tm_sec;
    struct tm tm_exp = *tm_now;
    tm_exp.tm_year += 10;
    exp.year = tm_exp.tm_year + 1900; exp.mon = tm_exp.tm_mon + 1; exp.day = tm_exp.tm_mday;
    exp.hour = tm_exp.tm_hour; exp.min = tm_exp.tm_min; exp.sec = tm_exp.tm_sec;
    mbedtls_x509write_crt_set_validity(&crt_write, &now, &exp);

    mbedtls_x509write_crt_set_md_alg(&crt_write, MBEDTLS_MD_SHA256);

    unsigned char certBuf[4096];
    int certLen = mbedtls_x509write_crt_pem(&crt_write, certBuf, sizeof(certBuf), mbedtls_ctr_drbg_random, &ctr_drbg);
    if (certLen < 0) {
        Serial.printf("Failed to write cert: %d\n", certLen);
        return;
    }
    certPEM = String((char*)certBuf, certLen);

    // Compute SHA-256 of cert for pinning
    unsigned char sha256[32];
    mbedtls_sha256((const unsigned char*)certPEM.c_str(), certPEM.length(), sha256, 0);
    char shaHex[65];
    for (int i = 0; i < 32; i++) sprintf(shaHex + i * 2, "%02x", sha256[i]);
    shaHex[64] = 0;
    certSHA256 = "sha256/" + String(shaHex);

    // Cleanup
    mbedtls_x509write_crt_free(&crt_write);
    mbedtls_x509_crt_free(&crt);
    mbedtls_pk_free(&key);
    mbedtls_ctr_drbg_free(&ctr_drbg);
    mbedtls_entropy_free(&entropy);

    Serial.println("Certificate generated.");
    Serial.print("Cert SHA-256: ");
    Serial.println(certSHA256);
}

// ============================================================
// Session Management
// ============================================================

void generateSessionNonce(uint8_t* nonce) {
    // Use ESP32 hardware RNG
    esp_fill_random(nonce, 32);
}

void createSession(const uint8_t* pinHash) {
    // Use hardware RNG for nonce
    esp_fill_random(currentSession.nonce, 32);
    memcpy(currentSession.pinHash, pinHash, 32);
    currentSession.createdAt = millis();
    currentSession.attempts = 0;
    currentSession.authorized = false;
    currentSession.active = true;
    currentSession.fileName[0] = 0;

    currentState = DeviceState::SESSION_PENDING;
    addLog("session_created");
    setLEDs(false, false, true); // Blue = session pending
    Serial.println("Session created. Waiting for physical approval.");
}

bool isSessionValid() {
    if (!currentSession.active) return false;
    if (millis() - currentSession.createdAt > SESSION_TTL_MS) {
        currentSession.active = false;
        addLog("session_expired");
        return false;
    }
    if (currentSession.attempts >= MAX_ATTEMPTS) {
        currentSession.active = false;
        addLog("session_locked");
        return false;
    }
    return true;
}

void expireSession() {
    currentSession.active = false;
    currentSession.authorized = false;
    currentState = DeviceState::OPERATIONAL;
    setLEDs(false, true, false); // Green = operational
    addLog("session_ended");
}

bool verifyPin(const uint8_t* pinHash) {
    return memcmp(pinHash, currentSession.pinHash, 32) == 0;
}

// ============================================================
// Button Handling (Interrupt + Debounce)
// ============================================================

void IRAM_ATTR buttonISR() {
    bool currentStateBtn = digitalRead(BUTTON_PIN);
    if (currentStateBtn == LOW && buttonLastState == HIGH) {
        // Falling edge - button pressed
        buttonPressStart = millis();
        buttonPressed = true;
    } else if (currentStateBtn == HIGH && buttonLastState == LOW) {
        // Rising edge - button released
        buttonPressed = false;
        unsigned long pressDuration = millis() - buttonPressStart;
        if (pressDuration >= AIRGAP_HOLD_MS) {
            buttonLongPress = true;
        }
    }
    buttonLastState = currentStateBtn;
}

void checkButton() {
    if (buttonLongPress) {
        buttonLongPress = false;
        Serial.println("LONG PRESS DETECTED - AIR GAP");
        triggerAirGap();
    }
    if (buttonPressed && (millis() - buttonPressStart > 50)) {
        // Debounced press detected
        buttonPressed = false;
        if (currentState == DeviceState::SESSION_PENDING) {
            currentSession.authorized = true;
            currentState = DeviceState::SESSION_AUTHORIZED;
            setLEDs(false, true, false); // Green = authorized
            addLog("session_authorized");
            Serial.println("PHYSICAL APPROVAL GRANTED");
        }
    }
}

void triggerAirGap() {
    Serial.println("=== AIR GAP TRIGGERED ===");
    addLog("air_gap_triggered");

    // Immediate WiFi shutdown
    httpsServerSock = -1;
    for (int i = 0; i < 4; i++) httpsClients[i].close();
    MDNS.end();
    WiFi.softAPdisconnect(true);
    WiFi.disconnect(true, true);
    WiFi.mode(WIFI_OFF);

    currentState = DeviceState::AIR_GAPPED;
    expireSession();

    // LEDs off
    setLEDs(false, false, false);

    // Restart after 2 seconds
    delay(2000);
    ESP.restart();
}

// ============================================================
// HTTPS Server (mbedTLS + lwIP)
// ============================================================

struct HTTPSClient {
    int sock = -1;
    mbedtls_ssl_context ssl;
    mbedtls_ssl_config conf;
    mbedtls_x509_crt cacert;
    mbedtls_pk_context pkey;
    bool ssl_init = false;

    ~HTTPSClient() { close(); }

    void close() {
        if (sock >= 0) { lwip_close(sock); sock = -1; }
        if (ssl_init) {
            mbedtls_ssl_free(&ssl);
            mbedtls_ssl_config_free(&conf);
            mbedtls_x509_crt_free(&cacert);
            mbedtls_pk_free(&pkey);
            ssl_init = false;
        }
    }
};

static HTTPSClient httpsClients[4];
static int httpsServerSock = -1;
static mbedtls_x509_crt serverCert;
static mbedtls_pk_context serverKey;
static bool serverCertInit = false;

void initServerCert() {
    if (serverCertInit) return;

    mbedtls_x509_crt_init(&serverCert);
    mbedtls_pk_init(&serverKey);

    int ret = mbedtls_x509_crt_parse(&serverCert, (const unsigned char*)certPEM.c_str(), certPEM.length() + 1);
    if (ret != 0) {
        Serial.printf("Failed to parse cert: %d\n", ret);
        return;
    }

    ret = mbedtls_pk_parse_key(&serverKey, (const unsigned char*)keyPEM.c_str(), keyPEM.length() + 1, NULL, 0, NULL, NULL);
    if (ret != 0) {
        Serial.printf("Failed to parse key: %d\n", ret);
        return;
    }

    serverCertInit = true;
    Serial.println("Server cert/key loaded");
}

void initHTTPSServer() {
    if (httpsServerSock >= 0) return;

    httpsServerSock = lwip_socket(AF_INET, SOCK_STREAM, 0);
    if (httpsServerSock < 0) {
        Serial.println("Failed to create HTTPS socket");
        return;
    }

    int opt = 1;
    lwip_setsockopt(httpsServerSock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(443);

    if (lwip_bind(httpsServerSock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        Serial.println("Failed to bind HTTPS socket");
        lwip_close(httpsServerSock);
        httpsServerSock = -1;
        return;
    }

    if (lwip_listen(httpsServerSock, 4) < 0) {
        Serial.println("Failed to listen on HTTPS socket");
        lwip_close(httpsServerSock);
        httpsServerSock = -1;
        return;
    }

    // Set non-blocking
    int flags = lwip_fcntl(httpsServerSock, F_GETFL, 0);
    lwip_fcntl(httpsServerSock, F_SETFL, flags | O_NONBLOCK);

    Serial.println("HTTPS server listening on port 443");
}

void handleHTTPSClients() {
    if (httpsServerSock < 0) return;

    // Accept new connections
    struct sockaddr_in clientAddr;
    socklen_t addrLen = sizeof(struct sockaddr_in);
    int clientSock = lwip_accept(httpsServerSock, (struct sockaddr*)&clientAddr, &addrLen);

    if (clientSock >= 0) {
        // Find free client slot
        for (int i = 0; i < 4; i++) {
            if (httpsClients[i].sock < 0) {
                httpsClients[i].sock = clientSock;

                // Set non-blocking
                int flags = lwip_fcntl(clientSock, F_GETFL, 0);
                lwip_fcntl(clientSock, F_SETFL, flags | O_NONBLOCK);

                // Initialize SSL
                mbedtls_ssl_init(&httpsClients[i].ssl);
                mbedtls_ssl_config_init(&httpsClients[i].conf);
                mbedtls_x509_crt_init(&httpsClients[i].cacert);
                mbedtls_pk_init(&httpsClients[i].pkey);

                // Setup SSL config
                mbedtls_ssl_config_init(&httpsClients[i].conf);
                int ret = mbedtls_ssl_config_defaults(&httpsClients[i].conf,
                    MBEDTLS_SSL_IS_SERVER,
                    MBEDTLS_SSL_TRANSPORT_STREAM,
                    MBEDTLS_SSL_PRESET_DEFAULT);
                if (ret != 0) {
                    Serial.printf("SSL config defaults failed: %d\n", ret);
                    lwip_close(httpsClients[i].sock);
                    httpsClients[i].sock = -1;
                    continue;
                }

                mbedtls_ssl_conf_authmode(&httpsClients[i].conf, MBEDTLS_SSL_VERIFY_NONE);
                mbedtls_ssl_conf_rng(&httpsClients[i].conf, mbedtls_ctr_drbg_random, NULL);

                // Setup cert/key
                mbedtls_ssl_conf_ca_chain(&httpsClients[i].conf, &serverCert, NULL);
                ret = mbedtls_ssl_conf_own_cert(&httpsClients[i].conf, &serverCert, &serverKey);
                if (ret != 0) {
                    Serial.printf("SSL conf own cert failed: %d\n", ret);
                    lwip_close(httpsClients[i].sock);
                    httpsClients[i].sock = -1;
                    continue;
                }

                ret = mbedtls_ssl_setup(&httpsClients[i].ssl, &httpsClients[i].conf);
                if (ret != 0) {
                    Serial.printf("SSL setup failed: %d\n", ret);
                    lwip_close(httpsClients[i].sock);
                    httpsClients[i].sock = -1;
                    continue;
                }

                mbedtls_ssl_set_bio(&httpsClients[i].ssl, &httpsClients[i].sock, 
                    mbedtls_net_send, mbedtls_net_recv, NULL);

                httpsClients[i].ssl_init = true;
                break;
            }
        }
    }

    // Process existing clients
    for (int i = 0; i < 4; i++) {
        if (httpsClients[i].sock < 0 || !httpsClients[i].ssl_init) continue;

        int ret = mbedtls_ssl_handshake(&httpsClients[i].ssl);
        if (ret == MBEDTLS_ERR_SSL_WANT_READ || ret == MBEDTLS_ERR_SSL_WANT_WRITE) {
            continue; // Handshake in progress
        }
        if (ret != 0) {
            // Handshake failed
            httpsClients[i].close();
            continue;
        }

        // Handshake complete, read request
        char buf[2048];
        int len = mbedtls_ssl_read(&httpsClients[i].ssl, (unsigned char*)buf, sizeof(buf) - 1);
        if (len <= 0) {
            if (len != MBEDTLS_ERR_SSL_WANT_READ && len != MBEDTLS_ERR_SSL_WANT_WRITE) {
                httpsClients[i].close();
            }
            continue;
        }

        buf[len] = 0;
        String request = String(buf);

        // Parse request (simplified)
        int firstSpace = request.indexOf(' ');
        int secondSpace = request.indexOf(' ', firstSpace + 1);
        String method = request.substring(0, firstSpace);
        String path = request.substring(firstSpace + 1, secondSpace);

        // Find end of headers
        int bodyStart = request.indexOf("\r\n\r\n");
        String body = (bodyStart >= 0) ? request.substring(bodyStart + 4) : "";

        // Route request
        String response;
        int statusCode = 200;
        String contentType = "application/json";

        if (path == "/api/session" && method == "POST") {
            // Parse body for PIN
            int pinStart = body.indexOf("pin=");
            if (pinStart >= 0) {
                pinStart += 4;
                int pinEnd = body.indexOf('&', pinStart);
                if (pinEnd < 0) pinEnd = body.length();
                String pin = body.substring(pinStart, pinEnd);
                pin.trim();

                if (pin.length() == 4 && pin.charAt(0) >= '0' && pin.charAt(0) <= '9') {
                    // Hash PIN and create session
                    mbedtls_sha256((const unsigned char*)pin.c_str(), pin.length(), currentSession.pinHash, 0);
                    createSession(currentSession.pinHash);

                    // Return session nonce
                    String nonceHex;
                    for (int j = 0; j < 32; j++) {
                        char buf[3];
                        sprintf(buf, "%02x", currentSession.nonce[j]);
                        nonceHex += buf;
                    }
                    response = "{\"session_nonce\":\"" + nonceHex + "\"}";
                } else {
                    response = "{\"error\":\"Enter exactly 4 digits\"}";
                }
            } else {
                response = "{\"error\":\"PIN required\"}";
            }
        } else if (path == "/api/session/status" && method == "GET") {
            String resp = "{";
            resp += "\"active\":" + String(currentSession.active ? "true" : "false");
            resp += ",\"authorized\":" + String(currentSession.authorized ? "true" : "false");
            resp += ",\"attempts\":" + String(currentSession.attempts);
            long ttl = currentSession.active ? (SESSION_TTL_MS - (millis() - currentSession.createdAt)) : 0;
            if (ttl < 0) ttl = 0;
            resp += ",\"ttl_remaining\":" + String(ttl);
            resp += "}";
            response = resp;
        } else if (path == "/api/session/authorize" && method == "POST") {
            if (!currentSession.active) {
                response = "{\"error\":\"No active session\"}";
            } else if (currentSession.authorized) {
                response = "{\"error\":\"Already authorized\"}";
            } else {
                currentSession.authorized = true;
                currentState = DeviceState::SESSION_AUTHORIZED;
                setLEDs(false, true, false);
                addLog("session_authorized_via_api");
                response = "{\"authorized\":true}";
            }
        } else if (path == "/cert") {
            response = certPEM;
        } else if (path == "/cert/sha256") {
            response = certSHA256;
        } else if (path == "/logs") {
            String json = "{\"logs\":[";
            for (int j = 0; j < logCount; j++) {
                json += "{\"time\":\"" + String(logs[j].timestamp) + "\",\"event\":\"" + String(logs[j].event) + "\"}";
                if (j < logCount - 1) json += ",";
            }
            json += "]}";
            response = json;
        } else if (path == "/api/files") {
            String json = "{\"files\":[";
            json += "{\"cid\":\"bafkreibljtkfhndytktic6tay36odejx4fd4zjkztnlnotppxu4ell5rcu\",";
            json += "\"name\":\"intel_report.pdf\",";
            json += "\"size\":245760,";
            json += "\"type\":\"application/pdf\"}";
            json += "]}";
            response = json;
        } else if (path == "/") {
            if (!currentSession.active) {
                response = "{\"error\":\"No active session\"}";
                statusCode = 403;
            } else if (!currentSession.authorized) {
                response = "{\"error\":\"Session not authorized. Physical button press required.\"}";
                statusCode = 403;
            } else {
                // Serve dashboard
                response = INDEX_HTML;
                contentType = "text/html";
            }
        } else {
            response = "{\"error\":\"Not found\"}";
            statusCode = 404;
        }

        // Send HTTP response
        String httpResponse = "HTTP/1.1 " + String(statusCode) + " OK\r\n";
        httpResponse += "Content-Type: " + contentType + "\r\n";
        httpResponse += "Content-Length: " + String(response.length()) + "\r\n";
        httpResponse += "Connection: close\r\n";
        httpResponse += "\r\n";
        httpResponse += response;

        mbedtls_ssl_write(&httpsClients[i].ssl, (const unsigned char*)httpResponse.c_str(), httpResponse.length());
        httpsClients[i].close();
    }
}

