void handleConnect() {
    if (!httpServer.hasArg("ssid") || !httpServer.hasArg("password")) {
        httpServer.send(400, "text/plain", "Missing SSID or password.");
        return;
    }

    targetSsid = httpServer.arg("ssid");
    targetPassword = httpServer.arg("password");
    targetSsid.trim();

    if (targetSsid.isEmpty()) {
        httpServer.send(400, "text/plain", "SSID cannot be empty.");
        return;
