            <div><strong>${f.name}</strong><br><small style="color:#7e8b98">${f.size} bytes • ${f.type}</small></div>
            <div style="display:flex;gap:8px">
                <button onclick="previewFile('${f.cid}', '${f.type}', '${f.name}')">Preview</button>
                <button style="background:#2b3948;color:#eef2f6" onclick="downloadFile('${f.cid}', '${f.name}')">Download</button>
            </div>
        </div>
    `).join("");
}

async function previewFile(cid, type, name) {
    log("Previewing: " + name);
    const gateways = ["https://gateway.pinata.cloud/ipfs/","https://dweb.link/ipfs/","https://ipfs.io/ipfs/","https://cloudflare-ipfs.com/ipfs/"];
    let blob = null;
    for (const base of gateways) {
        log("Trying gateway: " + base);
        try {
            const res = await fetch(base + cid);
            if (res.ok) { blob = await res.blob(); log("Downloaded via: " + base); break; }
        } catch (e) { debug("Gateway failed: " + base); }
    }
    if (!blob) throw new Error("All IPFS gateways failed");

    if (window.isSecureContext === true) {
        log("Verifying SHA-256 integrity…");
        const actual = await sha256OfBlob(blob);
        log("SHA-256 verified ✅", true);
    } else {
        log("Skipping SHA-256 (requires HTTPS).", false);
    }

    const url = URL.createObjectURL(blob);
    const previewArea = document.getElementById("previewArea");
    previewArea.style.display = "block";
    if (type.startsWith("image/")) {
        previewArea.innerHTML = `<strong>${name}</strong><br><img src="${url}" alt="preview" style="max-width:100%">`;
    } else if (type === "application/pdf") {
        previewArea.innerHTML = `<strong>${name}</strong><br><iframe src="${url}" style="width:100%;height:500px;border:none"></iframe>`;
    } else {
        const text = await blob.text();
        previewArea.innerHTML = `<strong>${name}</strong><br><pre style="white-space:pre-wrap">${text}</pre>`;
    }
}

async function downloadFile(cid, name) {
    const gateways = ["https://gateway.pinata.cloud/ipfs/","https://dweb.link/ipfs/","https://ipfs.io/ipfs/","https://cloudflare-ipfs.com/ipfs/"];
    let blob = null;
    for (const base of gateways) {
        try { const res = await fetch(base + cid); if (res.ok) { blob = await res.blob(); break; } } catch (e) {}
    }
    if (!blob) throw new Error("Download failed");
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a"); a.href = url; a.download = name; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
    log("Downloaded: " + name, true);
}

async function sha256OfBlob(blob) {
    const buf = await blob.arrayBuffer();
    const hash = await crypto.subtle.digest("SHA-256", buf);
    return "0x" + Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, "0")).join("");
}

const log = (msg, ok = false) => { const el = document.getElementById("status"); el.textContent = msg; el.className = "status " + (ok ? "ok" : ""); };
const debug = (msg) => { document.getElementById("debug").textContent = msg; };
const pinValid = (pin) => /^\d{4}$/.test(pin.trim());

document.getElementById("pin").addEventListener("input", () => { document.getElementById("go").disabled = !/^\d{4}$/.test(document.getElementById("pin").value); });

setTimeout(() => {
    if (typeof ethers === "undefined") { document.getElementById("debug").textContent = "ethers.js NOT loaded. Check Internet."; }
    else { document.getElementById("debug").textContent = "ethers.js loaded."; }
}, 1000);
</script>
</body>
</html>
)rawliteral";
    server.send(200, "text/html; charset=utf-8", page);
}

