#include <Arduino.h>
#include <WiFi.h>
#include <WebServer.h>
#include <ESPmDNS.h>
#include <mbedtls/sha256.h>

#include "index_html.h"

// ============================================================
// PROJECT AETHER — TACTICAL NODE (HTTP + PHYSICAL APPROVAL)
// ============================================================
// Flow:
//   1. Aether-Setup AP boots
//   2. Phone connects, enters hotspot creds via captive portal
//   3. ESP32 joins phone hotspot as STA (phone provides Internet)
//   4. mDNS advertises aether-node.local
//   4. HTTP server serves dashboard
//   5. Phone reconnects to hotspot, opens http://aether-node.local/
//   6. Login page loads, user enters PIN
//   7. Frontend computes keccak256(PIN + nonce), sends pinHash to /api/session
//   8. Dashboard queries blockchain with pinHash
//   9. Dashboard fetches file from IPFS, verifies AES-GCM tag
//  10. PHYSICAL BUTTON PRESS required to authorize session
//  11. File downloads, renders ephemerally
//  12. Session expires (60s TTL) or 3 failed attempts
//  13. Long button hold (3s) = immediate air-gap (WiFi OFF)
// ============================================================

// ---------- Provisioning AP ----------
static const char* SETUP_SSID = "Aether-Setup";
static const char* SETUP_PASSWORD = "aether1234";

// ---------- Final local hostname ----------
static const char* MDNS_HOSTNAME = "aether-node";

// ---------- Hardware pins ----------
static const int BUTTON_PIN = 4;        // GPIO 4 - Tactile button (active LOW with pullup)
static const int LED_RED_PIN = 18;      // GPIO 18 - Red LED
static const int LED_GREEN_PIN = 5;     // GPIO 5 - Green LED
static const int LED_BLUE_PIN = 19;     // GPIO 19 - Blue LED

// ---------- Session constants ----------
static const unsigned long SESSION_TTL_MS = 60000;      // 60 seconds
static const uint8_t MAX_ATTEMPTS = 3;                  // Max PIN attempts per session
static const unsigned long AIRGAP_HOLD_MS = 3000;       // 3 second hold = air-gap

// ---------- Web server ----------
WebServer server(80);

// ---------- State ----------
enum class DeviceState {
    BOOT,
    PROVISIONING_AP,
    PROVISIONING_STA,
    OPERATIONAL,
    SESSION_PENDING,
    SESSION_AUTHORIZED,
    SESSION_COMPLETE,
    AIR_GAPPED
};

DeviceState currentState = DeviceState::BOOT;

struct Session {
    uint8_t nonce[32];
    uint8_t pinHash[32];
    unsigned long createdAt = 0;
    uint8_t attempts = 0;
    bool authorized = false;
    bool active = false;
    char fileName[64] = {0};
};

Session currentSession;
bool staConnected = false;
bool provisioningComplete = false;
String targetSsid = "";
String targetPassword = "";

// Button debouncing
volatile bool buttonPressed = false;
volatile bool buttonLongPress = false;
unsigned long buttonPressStart = 0;
bool buttonLastState = HIGH;

// Log buffer (RAM only, lost on reboot)
struct LogEntry {
    char timestamp[20];
    char event[48];
};
LogEntry logs[16];
int logCount = 0;

// ============================================================
// Helpers
// ============================================================

void addLog(const char* event) {
    if (logCount >= 16) return;
    time_t now = time(nullptr);
    strftime(logs[logCount].timestamp, 20, "%Y-%m-%d %H:%M:%S", localtime(&now));
    strncpy(logs[logCount].event, event, 47);
    logCount++;
}

String htmlEscape(const String& input) {
    String out;
    out.reserve(input.length() + 16);
    for (size_t i = 0; i < input.length(); ++i) {
        char c = input[i];
        switch (c) {
            case '&': out += "&"; break;
            case '<': out += "<"; break;
            case '>': out += ">"; break;
            case '"': out += "\""; break;
            case '\'': out += "'"; break;
            default: out += c; break;
        }
    }
    return out;
}

void setLEDs(bool red, bool green, bool blue) {
    digitalWrite(LED_RED_PIN, red ? HIGH : LOW);
    digitalWrite(LED_GREEN_PIN, green ? HIGH : LOW);
    digitalWrite(LED_BLUE_PIN, blue ? HIGH : LOW);
}

void blinkLED(int pin, int times, int delayMs) {
    for (int i = 0; i < times; i++) {
        digitalWrite(pin, HIGH);
        delay(delayMs);
        digitalWrite(pin, LOW);
        delay(delayMs);
    }
}

bool isValidPin(const String& pin) {
    if (pin.length() != 4) return false;
    for (int i = 0; i < 4; i++) {
        if (pin[i] < '0' || pin[i] > '9') return false;
    }
    return true;
}

// ============================================================
// Session Management
// ============================================================

void generateSessionNonce(uint8_t* nonce) {
    esp_fill_random(nonce, 32);
}

void createSession(const uint8_t* pinHash) {
    esp_fill_random(currentSession.nonce, 32);
    memcpy(currentSession.pinHash, pinHash, 32);
    currentSession.createdAt = millis();
    currentSession.attempts = 0;
    currentSession.authorized = false;
    currentSession.active = true;
    currentSession.fileName[0] = 0;

    currentState = DeviceState::SESSION_PENDING;
    addLog("session_created");
    setLEDs(false, false, true); // Blue = session pending
    Serial.println("Session created. Waiting for physical approval.");
}

bool isSessionValid() {
    if (!currentSession.active) return false;
    if (millis() - currentSession.createdAt > SESSION_TTL_MS) {
        currentSession.active = false;
        addLog("session_expired");
        return false;
    }
    if (currentSession.attempts >= MAX_ATTEMPTS) {
        currentSession.active = false;
        addLog("session_locked");
        return false;
    }
    return true;
}

void expireSession() {
    currentSession.active = false;
    currentSession.authorized = false;
    currentState = DeviceState::OPERATIONAL;
    setLEDs(false, true, false); // Green = operational
    addLog("session_ended");
}

bool verifyPin(const uint8_t* pinHash) {
    return memcmp(pinHash, currentSession.pinHash, 32) == 0;
}

// ============================================================
// Button Handling (Interrupt + Debounce)
// ============================================================

void IRAM_ATTR buttonISR() {
    bool currentStateBtn = digitalRead(BUTTON_PIN);
    if (currentStateBtn == LOW && buttonLastState == HIGH) {
        buttonPressStart = millis();
        buttonPressed = true;
    } else if (currentStateBtn == HIGH && buttonLastState == LOW) {
        buttonPressed = false;
        unsigned long pressDuration = millis() - buttonPressStart;
        if (pressDuration >= AIRGAP_HOLD_MS) {
            buttonLongPress = true;
        }
    }
    buttonLastState = currentStateBtn;
}

// Forward declaration
void triggerAirGap();

void checkButton() {
    if (buttonLongPress) {
        buttonLongPress = false;
        Serial.println("LONG PRESS DETECTED - AIR GAP");
        triggerAirGap();
    }
    if (buttonPressed && (millis() - buttonPressStart > 50)) {
        buttonPressed = false;
        if (currentState == DeviceState::SESSION_PENDING) {
            currentSession.authorized = true;
            currentState = DeviceState::SESSION_AUTHORIZED;
            setLEDs(false, true, false); // Green = authorized
            addLog("session_authorized");
            Serial.println("PHYSICAL APPROVAL GRANTED");
        }
    }
}

void triggerAirGap() {
    Serial.println("=== AIR GAP TRIGGERED ===");
    addLog("air_gap_triggered");

    MDNS.end();
    WiFi.softAPdisconnect(true);
    WiFi.disconnect(true, true);
    WiFi.mode(WIFI_OFF);

    currentState = DeviceState::AIR_GAPPED;
    expireSession();

    setLEDs(false, false, false);

    delay(2000);
    ESP.restart();
}

// ============================================================
// Provisioning Pages (HTTP)
// ============================================================

