    else if (type === "application/pdf") { previewArea.innerHTML = `<strong>${name}</strong><br><iframe src="${url}" style="width:100%;height:500px;border:none"></iframe>`; }
    else { const text = await blob.text(); previewArea.innerHTML = `<strong>${name}</strong><br><pre style="white-space:pre-wrap">${text}</pre>`; }
}

async function downloadFile(cid, name) {
    const gateways = ["https://gateway.pinata.cloud/ipfs/","https://dweb.link/ipfs/","https://ipfs.io/ipfs/","https://cloudflare-ipfs.com/ipfs/"];
    let blob = null;
    for (const base of gateways) { try { const res = await fetch(base + cid); if (res.ok) { blob = await res.blob(); break; } } catch (e) {} }
