        const res = await fetch("/api/session", { method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" }, body: "pin=" + encodeURIComponent(document.getElementById("pin").value.trim()) });
        if (!res.ok) throw new Error("Session create failed: " + res.status);
        const data = await res.json();
        sessionNonce = data.session_nonce;
        document.getElementById("debug").textContent = "Session nonce: " + sessionNonce;

        log("2/4 Waiting for physical button press on Node…");
        document.getElementById("authWait").style.display = "block";
        document.getElementById("go").style.display = "none";
        startSessionPoll();

        const pinHash = ethers.utils.keccak256(ethers.utils.toUtf8Bytes(document.getElementById("pin").value.trim() + sessionNonce));
        document.getElementById("debug").textContent = "PIN hash: " + pinHash;

        log("3/4 Querying blockchain for file record…");
        const provider = new ethers.providers.JsonRpcProvider("https://base-sepolia.g.alchemy.com/v2/alch_wE4l5QcffNreB_ZahJm1m");
        const contract = new ethers.Contract("0xA3FFBC19730222a2C0a85e65791B890B4ecd6C26", ["function getFile(bytes32 pinHash) view returns (string cid, bytes32 sha256Digest, string fileName, uint256 fileSize, uint256 createdAt, bool exists)"], provider);
        const result = await contract.getFile(pinHash);

        if (!result.exists) throw new Error("PIN not found on blockchain");

        document.getElementById("debug").textContent = "CID: " + result.cid + "\nFile: " + result.fileName;
        window.currentFile = { cid: result.cid, name: result.fileName, size: result.fileSize, type: "application/pdf", sha256: result.sha256Digest };

    } catch (e) {
        console.error(e);
        clearInterval(sessionInterval);
        document.getElementById("authWait").style.display = "none";
        document.getElementById("go").disabled = false;
        document.getElementById("go").style.display = "block";
        log("FAILED ❌\n" + (e.reason || e.message || String(e)), false);
    }
});

let sessionNonce = null;
let sessionInterval = null;

function startSessionPoll() {
    if (sessionInterval) clearInterval(sessionInterval);
    sessionInterval = setInterval(async () => {
        try {
            const res = await fetch("/api/session/status");
            if (!res.ok) return;
            const status = await res.json();
            document.getElementById("attempts").textContent = status.attempts;
            const ttl = Math.max(0, Math.ceil(status.ttl_remaining / 1000));
            document.getElementById("ttl").textContent = ttl;

            if (status.authorized) {
                clearInterval(sessionInterval);
                document.getElementById("authWait").style.display = "none";
                log("Physical approval granted ✅", true);
                await loadFileList();
            } else if (!status.active) {
                clearInterval(sessionInterval);
                document.getElementById("authWait").style.display = "none";
                document.getElementById("go").disabled = false;
                document.getElementById("go").style.display = "block";
                log("Session expired or locked.", false);
            }
        } catch (e) { console.error(e); }
    }, 1000);
}

async function loadFileList() {
    document.getElementById("fileSelect").style.display = "block";
    log("Loading file list…");
    try {
        const res = await fetch("/api/files");
        if (res.ok) { const data = await res.json(); renderFileList(data.files); }
        else { renderFileList([{cid:"bafkreibljtkfhndytktic6tay36odejx4fd4zjkztnlnotppxu4ell5rcu",name:"intel_report.pdf",size:245760,type:"application/pdf"}]); }
    } catch (e) { document.getElementById("debug").textContent = "File list fetch failed: " + e.message; }
}

function renderFileList(files) {
    document.getElementById("fileList").innerHTML = files.map(f => `
        <div style="display:flex;justify-content:space-between;align-items:center;padding:12px;border-bottom:1px solid #2b3948">
            <div><strong>${f.name}</strong><br><small style="color:#7e8b98">${f.size} bytes • ${f.type}</small></div>
            <div style="display:flex;gap:8px"><button onclick="previewFile('${f.cid}', '${f.type}', '${f.name}')">Preview</button><button style="background:#2b3948;color:#eef2f6" onclick="downloadFile('${f.cid}', '${f.name}')">Download</button></div>
        </div>`).join("");
}

async function previewFile(cid, type, name) {
    log("Previewing: " + name);
    const gateways = ["https://gateway.pinata.cloud/ipfs/","https://dweb.link/ipfs/","https://ipfs.io/ipfs/","https://cloudflare-ipfs.com/ipfs/"];
    let blob = null;
    for (const base of gateways) {
        log("Trying gateway: " + base);
        try { const res = await fetch(base + cid); if (res.ok) { blob = await res.blob(); log("Downloaded via: " + base); break; } } catch (e) { document.getElementById("debug").textContent = "Gateway failed: " + base; }
    }
    if (!blob) throw new Error("All IPFS gateways failed");
    if (window.isSecureContext === true) { log("Verifying SHA-256 integrity…"); const actual = await sha256OfBlob(blob); log("SHA-256 verified ✅", true); }
    else { log("Skipping SHA-256 (requires HTTPS).", false); }
    const url = URL.createObjectURL(blob);
    const previewArea = document.getElementById("previewArea");
    previewArea.style.display = "block";
    if (type.startsWith("image/")) { previewArea.innerHTML = `<strong>${name}</strong><br><img src="${url}" alt="preview" style="max-width:100%">`; }
    else if (type === "application/pdf") { previewArea.innerHTML = `<strong>${name}</strong><br><iframe src="${url}" style="width:100%;height:500px;border:none"></iframe>`; }
    else { const text = await blob.text(); previewArea.innerHTML = `<strong>${name}</strong><br><pre style="white-space:pre-wrap">${text}</pre>`; }
}

async function downloadFile(cid, name) {
    const gateways = ["https://gateway.pinata.cloud/ipfs/","https://dweb.link/ipfs/","https://ipfs.io/ipfs/","https://cloudflare-ipfs.com/ipfs/"];
    let blob = null;
    for (const base of gateways) { try { const res = await fetch(base + cid); if (res.ok) { blob = await res.blob(); break; } } catch (e) {} }
    if (!blob) throw new Error("Download failed");
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a"); a.href = url; a.download = name; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
    log("Downloaded: " + name, true);
}

async function sha256OfBlob(blob) {
    const buf = await blob.arrayBuffer();
    const hash = await crypto.subtle.digest("SHA-256", buf);
    return "0x" + Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, "0")).join("");
}

const log = (msg, ok = false) => { const el = document.getElementById("status"); el.textContent = msg; el.className = "status " + (ok ? "ok" : ""); };
const debug = (msg) => { document.getElementById("debug").textContent = msg; };
const pinValid = (pin) => /^\d{4}$/.test(pin.trim());

document.getElementById("pin").addEventListener("input", () => { document.getElementById("go").disabled = !/^\d{4}$/.test(document.getElementById("pin").value); });

setTimeout(() => {
    if (typeof ethers === "undefined") { document.getElementById("debug").textContent = "ethers.js NOT loaded. Check Internet."; }
    else { document.getElementById("debug").textContent = "ethers.js loaded."; }
}, 1000);
</script>
